use super::*;
use crate::schema::{IdmlPart,diff::{IdmlPatch,IdmlPartPatch}};
#[test]
fn neutral_batches_keep_live_post_fields_and_admit_each_intermediate(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let mut post=IdmlSnapshot{dom_version:corpus["base"]["domVersion"].as_str().unwrap().into(),parts:corpus["base"]["parts"].as_array().unwrap().iter().map(|part|IdmlPart{path:part["path"].as_str().unwrap().into(),bytes:part["text"].as_str().unwrap().as_bytes().to_vec()}).collect()};if row["post"].is_object(){post.parts.iter_mut().find(|part|part.path==row["post"]["path"].as_str().unwrap()).unwrap().bytes=row["post"]["text"].as_str().unwrap().as_bytes().to_vec();}let diff=IdmlDiff{steps:row["steps"].as_array().unwrap().iter().map(|step|IdmlPatch{dom_version:step["domVersion"].as_str().map(str::to_string),part_order:step["partOrder"].as_array().map(|values|values.iter().map(|value|value.as_str().unwrap().to_string()).collect()),parts:step["parts"].as_array().unwrap().iter().map(|part|IdmlPartPatch{path:part["path"].as_str().unwrap().into(),bytes:if part["remove"]==true{None}else if let Some(text)=part["text"].as_str(){Some(text.as_bytes().to_vec())}else{Some(part["bytes"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect())}}).collect()}).collect()};let before=post.clone();let event=diff.clone();for work in [1,7,64,4096]{let mut cursor=IdmlOverlayCursor::new();let mut turns=0;let final_step=loop{turns+=1;assert!(turns<1000000);let step=cursor.advance(&post,&diff,IdmlAdmissionGrant{maximum_work:work,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24});assert!(step.work<=work);if step.done||step.error.is_some(){break step;}};if let Some(error)=row["error"].as_str(){assert_eq!(final_step.error,Some(error));}else{assert_eq!(final_step.error,None);let parts=(0..cursor.member_count().unwrap()).map(|index|{let(p,b)=cursor.member(index).unwrap();IdmlPart{path:name(&post,&diff,p).into(),bytes:data(&post,&diff,b).to_vec()}}).collect();let actual=IdmlSnapshot{dom_version:cursor.version_step().map_or_else(||post.dom_version.clone(),|step|diff.steps[step].dom_version.clone().unwrap()),parts};assert_eq!(actual,semio_framework_os_kernel::apply_diff_cold(&diff,&post).unwrap());if row["id"]=="preserve-live-post-field"{let(_,bytes)=cursor.member(2).unwrap();assert_eq!(bytes.step,None);assert_eq!(bytes.part,2);}}cursor.begin_close();while !cursor.terminal_is_empty(){let bytes=cursor.next_release_bytes();assert_eq!(cursor.close_one(bytes.saturating_sub(1)),if bytes==0{0}else{0});cursor.close_one(bytes);}assert_eq!(post,before);assert_eq!(diff,event);}for cut in [0,1,5,50]{let mut cursor=IdmlOverlayCursor::new();for _ in 0..cut{let step=cursor.advance(&post,&diff,IdmlAdmissionGrant{maximum_work:1,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24});if step.done||step.error.is_some(){break;}}cursor.begin_close();while !cursor.terminal_is_empty(){cursor.close_one(cursor.next_release_bytes());}assert_eq!(post,before);}}
}
